import{C as e,S as t,_ as n,c as r,d as i,f as a,g as o,i as s,l as c,m as l,n as u,o as d,w as f,x as p}from"./index-CkmND2NX.js";import{t as m}from"./navigate-DMkXde2y.js";window.salaryInterviewData={tiers:[{id:`junior`,range:`10 - 20 triệu`,min:10,max:20,label:`Junior Developer`,color:`#22c55e`,icon:`🌱`,description:`Mới ra trường hoặc 1-2 năm kinh nghiệm. Cần nắm vững nền tảng Java, SQL, OOP, Git.`,topics:[`Java Core: JDK/JRE/JVM, OOP, Collections, Exception`,`SQL cơ bản: SELECT, JOIN, GROUP BY, INDEX`,`Cấu trúc dữ liệu: Array, List, Map, Stack, Queue`,`Git cơ bản: commit, branch, merge`],questions:[{id:`j01`,topic:`Java Core`,difficulty:1,question:`Giải thích JDK, JRE, JVM và flow compile-run của Java. Tại sao Java gọi là "write once, run anywhere"?`,sampleAnswer:`JDK (Java Development Kit) bao gồm JRE + compiler (javac) + debugger + tools. JRE (Java Runtime Environment) bao gồm JVM + thư viện runtime cần thiết. JVM (Java Virtual Machine) là máy ảo thực thi bytecode (.class). Flow: Source (.java) → javac → Bytecode (.class) → JVM → Machine code (phụ thuộc OS). "Write once, run anywhere" nhờ JVM — bytecode giống nhau trên mọi nền tảng, JVM của từng OS sẽ dịch ra machine code tương ứng.`,keywords:[`JDK`,`JRE`,`JVM`,`bytecode`,`platform independence`]},{id:`j02`,topic:`Java Core`,difficulty:1,question:`Phân biệt ArrayList và LinkedList. Khi nào dùng cái nào? Cho ví dụ thực tế.`,sampleAnswer:`ArrayList: dùng dynamic array, truy cập index O(1), thêm/xóa giữa O(n) vì phải dịch phần tử. LinkedList: doubly linked list, truy cập O(n), thêm/xóa đầu/cuối O(1). Dùng ArrayList khi: random access nhiều, ít thêm/xóa giữa (VD: danh sách sản phẩm). Dùng LinkedList khi: thêm/xóa đầu/cuối liên tục (VD: hàng đợi xử lý tác vụ, undo stack). Bộ nhớ: ArrayList ít overhead, LinkedList tốn thêm cho node, prev, next.`,keywords:[`ArrayList`,`LinkedList`,`O(1)`,`O(n)`,`random access`]},{id:`j03`,topic:`OOP`,difficulty:1,question:`4 tính chất OOP là gì? Cho ví dụ cụ thể từng tính chất trong Java.`,sampleAnswer:`1. Đóng gói (Encapsulation): ẩn dữ liệu, chỉ truy cập qua getter/setter. VD: private String name; public String getName() { return name; }. 2. Kế thừa (Inheritance): class con kế thừa class cha. VD: class Dog extends Animal { }. 3. Đa hình (Polymorphism): cùng method nhưng hành vi khác nhau. VD: Animal a = new Dog(); a.speak(); // gọi Dog.speak(). 4. Trừu tượng (Abstraction): chỉ định nghĩa interface/abstract class, không implement chi tiết. VD: abstract class Animal { abstract void move(); }.`,keywords:[`encapsulation`,`inheritance`,`polymorphism`,`abstraction`]},{id:`j04`,topic:`Java Core`,difficulty:1,question:`Phân biệt == và equals(). Tại sao phải override hashCode khi override equals?`,sampleAnswer:`== so sánh reference (địa chỉ vùng nhớ) đối với object, so sánh giá trị với primitive. equals() so sánh nội dung (đã được override ở các class như String, Integer). Quy tắc: nếu a.equals(b) == true thì a.hashCode() == b.hashCode() (bắt buộc). Ngược lại không bắt buộc. Nếu chỉ override equals mà không override hashCode, HashMap sẽ lưu object vào bucket sai — khi get sẽ không tìm thấy vì hash khác nhau.`,keywords:[`==`,`equals`,`hashCode`,`contract`,`HashMap`]},{id:`j05`,topic:`Exception`,difficulty:1,question:`Phân biệt Checked và Unchecked Exception. try-with-resources là gì?`,sampleAnswer:`Checked Exception: kế thừa Exception (trừ RuntimeException), compiler bắt buộc xử lý bằng try-catch hoặc throws. VD: IOException, SQLException, FileNotFoundException. Unchecked Exception: kế thừa RuntimeException, không bắt buộc xử lý. VD: NullPointerException, ArrayIndexOutOfBoundsException, IllegalArgumentException. try-with-resources (Java 7+): tự động đóng resource implements AutoCloseable. VD: try (BufferedReader br = new BufferedReader(new FileReader("file.txt"))) { br.readLine(); } // auto close.`,keywords:[`checked`,`unchecked`,`try-with-resources`,`AutoCloseable`]},{id:`j06`,topic:`SQL`,difficulty:2,question:`Viết câu SQL: lấy top 5 nhân viên có lương cao nhất mỗi phòng ban. Giải thích từng phần.`,sampleAnswer:`SELECT department, employee_name, salary FROM (SELECT department, employee_name, salary, ROW_NUMBER() OVER (PARTITION BY department ORDER BY salary DESC) AS rn FROM employees) ranked WHERE rn <= 5; Giải thích: ROW_NUMBER() đánh số thứ tự theo lương giảm dần, PARTITION BY department chia riêng từng phòng, subquery lọc lấy top 5 mỗi phòng. Có thể dùng DENSE_RANK() nếu muốn đồng hạng.`,keywords:[`ROW_NUMBER`,`PARTITION BY`,`window function`,`subquery`]},{id:`j07`,topic:`Data Structures`,difficulty:2,question:`HashMap hoạt động thế nào? Collision xử lý ra sao? Tại sao initial capacity và load factor quan trọng?`,sampleAnswer:`HashMap hoạt động: 1. Tính hashCode() của key. 2. Tính bucket index = (n - 1) & hash (n là capacity). 3. Nếu bucket trống → lưu entry. 4. Nếu collision → dùng equals() để tìm key đúng. Collision: Java 8 trước dùng LinkedList, Java 8+ nếu ≥ 8 entries chuyển sang Red-Black Tree (nếu key implement Comparable). Initial capacity mặc định 16, load factor 0.75 — khi kích thước > capacity * 0.75 thì resize gấp đôi và rehash. Chọn initial capacity phù hợp giảm resize (tốn O(n)).`,keywords:[`hashCode`,`bucket`,`collision`,`load factor`,`resize`]},{id:`j08`,topic:`Git`,difficulty:1,question:`Git merge và git rebase khác nhau thế nào? Khi nào dùng cái nào?`,sampleAnswer:`Merge: tạo merge commit, giữ nguyên lịch sử branch. Dùng khi muốn giữ lịch sử thật (feature branch, public branch). Rebase: đặt commits của branch hiện tại lên đỉnh của branch target, lịch sử thẳng. Dùng khi muốn lịch sử sạch (personal branch, trước khi merge lên main). Nguyên tắc: không rebase branch đã push lên remote và nhiều người dùng chung. Git flow: feature branch → rebase lên main → merge tạo merge commit.`,keywords:[`merge`,`rebase`,`commit history`,`golden rule`]},{id:`j09`,topic:`Java Core`,difficulty:2,question:`String immutable nghĩa là gì? StringBuilder vs StringBuffer khác nhau thế nào?`,sampleAnswer:`String immutable nghĩa là không thể thay đổi sau khi tạo. Mỗi lần + là tạo object mới trong String Pool. Lợi ích: thread-safe, hashcode ổn định (dùng làm HashMap key), String Pool tiết kiệm bộ nhớ. StringBuilder: không thread-safe, nhanh hơn (dùng khi xử lý chuỗi trong method local). StringBuffer: thread-safe (synchronized methods), chậm hơn. VD: StringBuilder sb = new StringBuilder(); sb.append("Hello").append(" ").append("World"); // "Hello World" — chỉ tạo 1 object.`,keywords:[`immutable`,`String Pool`,`StringBuilder`,`StringBuffer`,`thread-safe`]},{id:`j10`,topic:`SQL`,difficulty:1,question:`Các loại JOIN trong SQL? INNER JOIN khác LEFT JOIN thế nào?`,sampleAnswer:`INNER JOIN: chỉ lấy dòng có match ở cả 2 bảng (giao). LEFT JOIN: lấy tất cả bảng trái, null nếu không match bảng phải. RIGHT JOIN: lấy tất cả bảng phải. FULL OUTER JOIN: lấy tất cả cả 2 bảng. CROSS JOIN: tích Descartes. VD: SELECT u.name, o.order_date FROM users u LEFT JOIN orders o ON u.id = o.user_id — lấy tất cả user, kể cả chưa có đơn hàng (order_date = null). INNER JOIN sẽ chỉ lấy user có ít nhất 1 đơn.`,keywords:[`INNER JOIN`,`LEFT JOIN`,`RIGHT JOIN`,`FULL OUTER JOIN`]},{id:`j11`,topic:`OOP`,difficulty:1,question:`Overloading vs Overriding khác nhau thế nào? Cho ví dụ.`,sampleAnswer:`Overloading (nạp chồng): cùng tên method, khác tham số (số lượng, kiểu, thứ tự), xảy ra trong cùng class, quyết định tại compile time. VD: int add(int a, int b) và double add(double a, double b). Overriding (ghi đè): class con viết lại method của class cha, cùng tên và tham số, quyết định tại runtime. VD: @Override public String toString() { return name; }. Overriding không thể giảm access modifier (public → protected là lỗi).`,keywords:[`overloading`,`overriding`,`compile time`,`runtime`,`@Override`]},{id:`j12`,topic:`Java Core`,difficulty:2,question:`Interface vs Abstract class khác nhau thế nào? Java 8+ có gì mới?`,sampleAnswer:`Abstract class: có thể có constructor, fields, methods (abstract + concrete), extends. Interface: chỉ có abstract methods (Java 7), từ Java 8 có default + static methods, Java 9 có private methods. Đa kế thừa: class implements nhiều interface, extends 1 abstract class. Chọn abstract class khi các class con chia sẻ state/behavior. Chọn interface khi định nghĩa contract/hành vi. VD: List là interface, AbstractList là abstract class, ArrayList extends AbstractList implements List.`,keywords:[`interface`,`abstract class`,`default method`,`multiple inheritance`]},{id:`j13`,topic:`Data Structures`,difficulty:1,question:`Stack và Queue khác nhau thế nào? Ứng dụng thực tế?`,sampleAnswer:`Stack: LIFO (Last In First Out). Thêm/pop ở đỉnh. Dùng: undo (Ctrl+Z), call stack trong JVM, duyệt cây (DFS), kiểm tra ngoặc. Queue: FIFO (First In First Out). Thêm ở cuối, lấy ở đầu. Dùng: scheduling, xử lý tác vụ, breadth-first search. Trong Java: Deque<String> stack = new ArrayDeque<>(); stack.push("A"); stack.pop(); Queue<String> queue = new LinkedList<>(); queue.offer("A"); queue.poll();`,keywords:[`Stack`,`Queue`,`LIFO`,`FIFO`,`Deque`]},{id:`j14`,topic:`Git`,difficulty:1,question:`Git conflict là gì? Cách resolve conflict? Git stash dùng khi nào?`,sampleAnswer:`Git conflict xảy ra khi 2 branch cùng sửa 1 file ở cùng dòng. Resolve: git merge → conflict markers (<<<<<<, ======, >>>>>>) → sửa thủ công → git add → git commit. Git stash: tạm thời cất thay đổi chưa commit để làm việc khác. git stash save "msg", git stash pop, git stash list. Dùng khi: đang code dang dở, cần checkout branch khác gấp. Có thể stash staged/untracked riêng.`,keywords:[`conflict`,`merge conflict`,`stash`,`markers`]},{id:`j15`,topic:`Java Core`,difficulty:1,question:`final, finally, finalize khác nhau thế nào?`,sampleAnswer:`final: keyword dùng cho class (không thể extends), method (không thể override), variable (hằng số). finally: khối trong try-catch, luôn chạy dù có exception hay không — dùng để đóng resource (trước Java 7). finalize(): method của Object, được GC gọi trước khi thu hồi object — không nên dùng (không đảm bảo thời điểm chạy, deprecated từ Java 9). VD: try { ... } catch (...) { ... } finally { conn.close(); }.`,keywords:[`final`,`finally`,`finalize`,`GC`,`deprecated`]},{id:`j16`,topic:`SQL`,difficulty:2,question:`INDEX là gì? Ưu nhược điểm? Khi nào không nên dùng INDEX?`,sampleAnswer:`INDEX là cấu trúc dữ liệu (thường B-Tree) giúp tăng tốc truy vấn WHERE, JOIN, ORDER BY. Ưu: tìm kiếm nhanh hơn (O(log n) thay vì O(n) full scan). Nhược: tốn dung lượng, INSERT/UPDATE/DELETE chậm hơn vì phải cập nhật index. Không nên dùng: cột có cardinality thấp (giới tính: chỉ 2 giá trị), bảng nhỏ (vài trăm dòng), cột thường xuyên update. Composite index cho nhiều cột: CREATE INDEX idx_name ON users(last_name, first_name) — áp dụng left-most prefix.`,keywords:[`INDEX`,`B-Tree`,`cardinality`,`composite index`,`full scan`]}]},{id:`middle`,range:`20 - 40 triệu`,min:20,max:40,label:`Middle Developer`,color:`#3b82f6`,icon:`📈`,description:`2-5 năm kinh nghiệm. Cần hiểu Spring Boot, JPA, REST, Multithreading, Transaction, Security.`,topics:[`Spring Boot: autoconfig, DI, AOP, Actuator, testing`,`REST API: thiết kế, validation, error handling, versioning`,`JPA/Hibernate: N+1, caching, relationships, inheritance`,`Multithreading: thread pool, synchronized, deadlock, concurrent collections`,`Transaction: ACID, isolation levels, propagation, @Transactional`,`Security: JWT, OAuth2, Spring Security, CORS, CSRF`,`Testing: JUnit 5, Mockito, Integration test, Testcontainers`],questions:[{id:`m01`,topic:`Spring Boot`,difficulty:2,question:`Spring Boot autoconfiguration hoạt động thế nào? Làm sao để custom?`,sampleAnswer:`@EnableAutoConfiguration (hoặc @SpringBootApplication) scan spring.factories trong META-INF của các dependency. Mỗi auto-config class có @Conditional (OnClass, OnBean, OnProperty, OnMissingBean). VD: có H2 trong classpath và không có DataSource bean → auto config DataSource. Custom: exclude class trong @EnableAutoConfiguration, override bằng bean của mình (@ConditionalOnMissingBean), hoặc set property trong application.properties. Tự tạo auto-config: tạo class + spring.factories.`,keywords:[`@EnableAutoConfiguration`,`spring.factories`,`@Conditional`,`auto-config`]},{id:`m02`,topic:`Spring Boot`,difficulty:2,question:`Phân biệt @Component, @Service, @Repository, @Controller. Đặc điểm của @Repository?`,sampleAnswer:`@Component: stereotype tổng quát, Spring scan để tạo bean. @Service: cho business layer, chỉ là semantic (không thêm behavior). @Repository: cho DAO layer, Spring tự động chuyển đổi SQLException thành DataAccessException (PersistenceExceptionTranslationPostProcessor). @Controller: cho web layer, hỗ trợ handler mapping. @RestController = @Controller + @ResponseBody. Nên dùng đúng stereotype để dễ maintain và AOP pointcut chính xác.`,keywords:[`@Component`,`@Service`,`@Repository`,`@Controller`,`stereotype`]},{id:`m03`,topic:`JPA`,difficulty:3,question:`N+1 problem trong Hibernate là gì? Phân tích các cách fix và ưu nhược điểm.`,sampleAnswer:`N+1 xảy ra khi 1 query lấy N entities, sau đó N query riêng cho từng quan hệ. VD: lấy 100 đơn hàng → 1 query orders + 100 query user cho mỗi order. Cách fix: 1. JOIN FETCH: @Query("SELECT o FROM Order o JOIN FETCH o.user") — eager loading, nhưng nếu có nhiều collection thì Cartesian product. 2. @EntityGraph: @EntityGraph(attributePaths = {"user"}) — linh hoạt hơn JOIN FETCH. 3. Batch fetching: @BatchSize(size = 10) — gom N entities vào 1 query (N/10 query). 4. DTO projection: SELECT new OrderDTO(o.id, u.name) FROM Order o JOIN o.user u — chỉ lấy field cần. Chọn JOIN FETCH cho quan hệ bắt buộc, batch cho optional.`,keywords:[`N+1`,`JOIN FETCH`,`@EntityGraph`,`@BatchSize`,`DTO projection`]},{id:`m04`,topic:`Multithreading`,difficulty:2,question:`Synchronized hoạt động thế nào? Phân biệt synchronized method, block, static method.`,sampleAnswer:`synchronized dùng intrinsic lock (monitor) của object. Method: public synchronized void inc() { count++; } — lock trên this (instance) hoặc Class (static). Block: synchronized(this) { count++; } — linh hoạt, lock trên object bất kỳ. Static method: public static synchronized void inc() — lock trên Class object. Khác biệt: synchronized method lock toàn bộ method, block có thể lock phần code nhỏ, giảm contention. ReentrantLock: có tryLock, lockInterruptibly, công bằng — linh hoạt hơn synchronized.`,keywords:[`synchronized`,`intrinsic lock`,`monitor`,`ReentrantLock`,`contention`]},{id:`m05`,topic:`Transaction`,difficulty:3,question:`4 isolation levels và các vấn đề dirty read, non-repeatable read, phantom read. MySQL InnoDB mặc định?`,sampleAnswer:`READ UNCOMMITTED: có dirty read (đọc dữ liệu chưa commit), non-repeatable read, phantom. READ COMMITTED (PostgreSQL, Oracle mặc định): không dirty read, có non-repeatable và phantom. REPEATABLE READ (MySQL InnoDB mặc định): không dirty, không non-repeatable, có phantom (nhưng InnoDB dùng gap lock để ngăn). SERIALIZABLE: không vấn đề nào, chậm nhất. Dirty read: transaction A đọc dữ liệu B chưa commit → B rollback. Non-repeatable: đọc cùng dòng 2 lần khác nhau. Phantom: đọc WHERE condition 2 lần, số dòng khác nhau.`,keywords:[`isolation level`,`dirty read`,`phantom read`,`gap lock`,`MVCC`]},{id:`m06`,topic:`REST API`,difficulty:2,question:`Thiết kế REST API cho module "đặt hàng" hoàn chỉnh. Nêu endpoints, status codes, error handling.`,sampleAnswer:`POST /api/orders — tạo đơn (201 Created). GET /api/orders — danh sách (200). GET /api/orders/{id} — chi tiết (200/404). PUT /api/orders/{id}/cancel — hủy (200/400 nếu đã giao). GET /api/orders/{id}/items — items của đơn (200). Pagination: GET /api/orders?page=0&size=20&sort=createdAt,desc. Error: 400 Bad Request (validation), 401 Unauthorized, 403 Forbidden, 404 Not Found, 409 Conflict (trùng), 500 Internal. Response chuẩn: { "status": 400, "message": "Order already shipped", "timestamp": "...", "errors": [...], "path": "/api/orders/1/cancel" }. Dùng @ControllerAdvice + @ExceptionHandler.`,keywords:[`RESTful`,`status code`,`pagination`,`error handling`,`@ControllerAdvice`]},{id:`m07`,topic:`Security`,difficulty:3,question:`JWT gồm những phần nào? Luồng access token + refresh token? Cách revoke JWT?`,sampleAnswer:`JWT gồm 3 phần: Header (alg, typ) . Payload (sub, iat, exp, role) . Signature (HMAC-SHA256 hoặc RSA). Luồng: login → server trả access token (ngắn hạn, 15-30p) + refresh token (dài hạn, 7-30 ngày, lưu DB). Client gửi access token trong header Authorization: Bearer <token>. Hết hạn → gửi refresh token → server cấp access token mới. Revoke JWT: không thể revoke stateless JWT. Giải pháp: blacklist (lưu revoked tokens vào Redis/DB — mất stateless), dùng refresh token short-lived, hoặc chuyển sang opaque token. Lưu refresh token httpOnly cookie, secure, sameSite=Strict.`,keywords:[`JWT`,`access token`,`refresh token`,`revoke`,`blacklist`]},{id:`m08`,topic:`Spring Boot`,difficulty:3,question:`Cấu hình và quản lý nhiều datasource trong Spring Boot? Xử lý transaction giữa 2 datasource?`,sampleAnswer:`Tách riêng config class cho mỗi datasource: @Configuration @EnableTransactionManagement @EnableJpaRepositories(basePackages = "...", entityManagerFactoryRef = "emf1", transactionManagerRef = "tm1"). Tạo @Primary cho datasource chính. Mỗi datasource có riêng DataSource, EntityManagerFactory, TransactionManager. XA transaction cho 2 datasource: dùng Atomikos hoặc Narayana — 2PC (slow). Cách đơn giản hơn: saga pattern (eventual consistency) hoặc Best Effort 1PC (dùng @ChainedTransactionManager). Transaction giữa DB và Kafka: Outbox pattern (lưu event vào DB, CDC capture và push lên Kafka).`,keywords:[`multiple datasource`,`@Primary`,`XA`,`Atomikos`,`Outbox pattern`]},{id:`m09`,topic:`Multithreading`,difficulty:3,question:`Deadlock là gì? 4 điều kiện deadlock và cách phòng tránh. Cho ví dụ.`,sampleAnswer:`4 điều kiện: 1. Mutual exclusion — resource chỉ 1 thread dùng. 2. Hold and wait — thread giữ resource và chờ resource khác. 3. No preemption — không thể lấy resource từ thread khác. 4. Circular wait — vòng tròn chờ nhau. VD: Thread A lock obj1, chờ obj2. Thread B lock obj2, chờ obj1. Cách phòng tránh: 1. Lock theo cùng thứ tự (always lock obj1 → obj2). 2. Dùng tryLock với timeout (ReentrantLock.tryLock(1s)). 3. Dùng Lock-Free cấu trúc (ConcurrentHashMap, AtomicReference). 4. Hạn chế số lượng lock tối thiểu.`,keywords:[`deadlock`,`circular wait`,`tryLock`,`lock ordering`,`lock-free`]},{id:`m10`,topic:`JPA`,difficulty:2,question:`Caching trong Hibernate: L1 cache, L2 cache, query cache. Khi nào dùng?`,sampleAnswer:`L1 cache (Session/EntityManager): mặc định, trong 1 session, entity load 1 lần. Không tắt được. L2 cache (SessionFactory): chia sẻ giữa các session, cần cấu hình (EHCache, Redis, Caffeine). Cache entity: @Cache(usage = CacheConcurrencyStrategy.READ_WRITE). Query cache: cache kết quả query + parameters, cần @Cacheable và query.setCacheable(true). Khi nào dùng L2: dữ liệu ít thay đổi (reference data, danh mục). Không dùng: dữ liệu thường xuyên update (transactions, logs). Lưu ý: L2 cache không đồng bộ giữa các instance — cần distributed cache (Redis).`,keywords:[`L1 cache`,`L2 cache`,`query cache`,`EHCache`,`cache strategy`]},{id:`m11`,topic:`Testing`,difficulty:2,question:`Viết unit test cho service layer với JUnit 5 + Mockito. Các loại test trong Spring Boot?`,sampleAnswer:`@SpringBootTest: full context — integration test. @WebMvcTest: chỉ tầng web. @DataJpaTest: chỉ JPA repository. @MockBean: mock bean vào Spring context. Unit test: @ExtendWith(MockitoExtension.class), @Mock, @InjectMocks. VD: @Test void whenOrderValid_thenCreated() { when(orderRepo.save(any())).thenReturn(mockOrder); Order result = orderService.create(request); assertThat(result.getId()).isNotNull(); }. Integration test: Testcontainers cho database thật, @SpringBootTest + @Testcontainers. Code coverage > 80%. Given-When-Then pattern cho readability.`,keywords:[`JUnit 5`,`Mockito`,`@SpringBootTest`,`@WebMvcTest`,`Testcontainers`]},{id:`m12`,topic:`REST API`,difficulty:2,question:`Validation trong Spring Boot: @Valid, @Validated, custom validator. Nêu các annotation thường dùng.`,sampleAnswer:`@Valid: trigger validation trên request body. @Validated: dùng cho group validation. @NotNull: không null. @NotEmpty: không null và không empty (String, Collection). @NotBlank: không null và có ít nhất 1 ký tự không space. @Size(min, max): giới hạn độ dài. @Pattern(regexp): định dạng. @Email: kiểm tra email format. @Min/@Max: số tối thiểu/tối đa. Custom validator: tạo annotation + class implements ConstraintValidator. VD: @PhoneVietnam — regex bắt đầu bằng 0, 10 số. Global exception: @RestControllerAdvice + @ExceptionHandler(MethodArgumentNotValidException.class) để trả về lỗi đẹp.`,keywords:[`@Valid`,`@Validated`,`validation annotation`,`custom validator`,`@RestControllerAdvice`]},{id:`m13`,topic:`Spring Boot`,difficulty:2,question:`AOP trong Spring Boot: @Aspect, @Around, @Before, @After. Ứng dụng thực tế?`,sampleAnswer:`AOP (Aspect Oriented Programming): tách cross-cutting concerns khỏi business logic. @Before: chạy trước method. @After: chạy sau (bất kể thành công hay lỗi). @AfterReturning: chạy sau khi thành công. @AfterThrowing: chạy sau khi ném exception. @Around: bao quanh method — có thể quyết định có gọi method hay không. Ứng dụng: logging (log method entry/exit + thời gian), transaction (@Transactional dùng AOP), security (@PreAuthorize), caching (@Cacheable), auditing (ghi log thay đổi dữ liệu). @Around("@annotation(Loggable)") — tự tạo annotation cho method cần log.`,keywords:[`AOP`,`@Aspect`,`@Around`,`cross-cutting`,`logging`]},{id:`m14`,topic:`Security`,difficulty:2,question:`Spring Security: SecurityFilterChain, authentication manager, password encoder?`,sampleAnswer:`@Bean SecurityFilterChain: định nghĩa security rules — authorizeHttpRequests, formLogin, oauth2Login, csrf, cors. AuthenticationManager: authenticate() nhận Authentication object. ProviderManager chứa nhiều AuthenticationProvider. DaoAuthenticationProvider: lấy user từ UserDetailsService, so sánh password bằng PasswordEncoder. BCryptPasswordEncoder: mặc định, dùng BCrypt hash (salt tự động). Tạo JWT filter: extends OncePerRequestFilter, parse JWT từ header, tạo UsernamePasswordAuthenticationToken, set SecurityContextHolder. CORS: @CrossOrigin hoặc CorsConfigurationSource bean.`,keywords:[`SecurityFilterChain`,`AuthenticationManager`,`BCrypt`,`JWT filter`,`CORS`]},{id:`m15`,topic:`Multithreading`,difficulty:2,question:`ExecutorService và Thread Pool: các loại pool, cách chọn, best practices.`,sampleAnswer:`Executors.newFixedThreadPool(n): pool cố định — cho CPU-bound tasks. newCachedThreadPool(): pool không giới hạn, reuse thread — cho IO-bound tasks, short-lived. newSingleThreadExecutor(): 1 thread — cho sequential tasks. ScheduledThreadPoolExecutor: schedule, delay, periodic tasks. Best practices: luôn shutdown pool (shutdown() + awaitTermination()). Dùng ThreadPoolExecutor custom: corePoolSize, maxPoolSize, keepAliveTime, BlockingQueue. CPU-bound: pool size = số core CPU + 1. IO-bound: pool size = 2 * số core CPU. Dùng ThreadFactory để đặt tên thread (giúp debug).`,keywords:[`ExecutorService`,`Thread Pool`,`fixedThreadPool`,`cachedThreadPool`,`ThreadPoolExecutor`]},{id:`m16`,topic:`Transaction`,difficulty:3,question:`@Transactional propagation levels: REQUIRED, REQUIRES_NEW, NESTED khác nhau thế nào?`,sampleAnswer:`REQUIRED (mặc định): dùng transaction hiện tại, nếu không có thì tạo mới. REQUIRES_NEW: luôn tạo transaction mới, suspend transaction cũ — VD: log lỗi không rollback transaction chính. NESTED: tạo savepoint bên trong transaction hiện tại — rollback về savepoint, không rollback toàn bộ. MANDATORY: phải có transaction, nếu không có thì ném exception. NEVER: không được có transaction. SUPPORTS: có transaction thì dùng, không có thì không sao. NOT_SUPPORTED: suspend transaction hiện tại, chạy không transaction. Lưu ý: NESTED chỉ dùng được với JDBC savepoint (không phải database nào cũng hỗ trợ).`,keywords:[`@Transactional`,`propagation`,`REQUIRES_NEW`,`NESTED`,`savepoint`]},{id:`m17`,topic:`JPA`,difficulty:2,question:`Các quan hệ JPA: @OneToOne, @OneToMany, @ManyToMany. Fetch type LAZY vs EAGER?`,sampleAnswer:`@OneToOne: user ↔ profile. @OneToMany: user có nhiều orders. @ManyToOne: order thuộc về user — @ManyToOne mặc định EAGER (các quan hệ khác LAZY). @ManyToMany: student ↔ course. Fetch type: LAZY — load khi truy cập (proxy), cần trong transaction. EAGER — load ngay (JOIN hoặc SELECT). EAGER dễ gây N+1 nếu dùng sai. @JoinColumn: định nghĩa khóa ngoại. @JoinTable: cho ManyToMany. Cascade: ALL, PERSIST, MERGE, REMOVE — cẩn thận khi dùng cascade REMOVE (xóa cha → xóa con). orphanRemoval = true: xóa con khi remove khỏi collection.`,keywords:[`@OneToMany`,`@ManyToMany`,`LAZY`,`EAGER`,`cascade`]},{id:`m18`,topic:`Spring Boot`,difficulty:2,question:`Spring Boot Actuator: endpoints, custom health indicator, security?`,sampleAnswer:`Actuator cung cấp production-ready endpoints: /health (DB, disk, custom), /metrics (JVM, request, cache), /info (custom), /env (environment properties), /loggers, /mappings, /threaddump, /heapdump. Custom health: implements HealthIndicator — check DB, external API, disk space. Security: các endpoints nhạy cảm (env, heapdump) cần authenticated. management.endpoints.web.exposure.include=health,info. Quan trọng: không expose actuator ra public network, hoặc secure bằng Spring Security. Metrics: Micrometer — prometheus, grafana integration cho production monitoring.`,keywords:[`Actuator`,`/health`,`/metrics`,`HealthIndicator`,`Micrometer`]}]},{id:`senior`,range:`40 - 70 triệu`,min:40,max:70,label:`Senior Developer`,color:`#8b5cf6`,icon:`🎯`,description:`5-8 năm kinh nghiệm. Cần hiểu kiến trúc microservices, cloud, performance, design patterns.`,topics:[`Microservices: tách service, giao tiếp inter-service, API Gateway, distributed tracing`,`Docker & Kubernetes: container, orchestration, rolling update, liveness/readiness probe`,`Message Queue: Kafka, RabbitMQ, event-driven, stream processing`,`Cloud: AWS/GCP, auto-scaling, load balancer, S3, RDS, Lambda`,`Performance: caching distributed, connection pool sizing, query optimization, profiling`,`Design Patterns: Singleton, Factory, Strategy, Observer, Builder, Proxy`,`Observability: logging (ELK), metrics (Prometheus), tracing (Jaeger)`],questions:[{id:`s01`,topic:`Microservices`,difficulty:3,question:`Microservices giao tiếp với nhau thế nào? Phân tích REST, gRPC, message queue — khi nào chọn cái nào?`,sampleAnswer:`REST sync: đơn giản, dễ debug (curl), dùng cho CRUD, request-response. Nhược: chậm (JSON text), không có contract chặt chẽ. gRPC: nhanh (Protocol Buffers binary), streaming, contract-first (proto file), code generation tự động. Dùng cho service-to-service latency-critical. Message Queue (Kafka/RabbitMQ): async, decouple, buffered, event-driven. Dùng cho: notification, CDC, event sourcing, xử lý batch. Chọn: API Gateway gọi REST/gRPC cho user-facing. Event bus dùng Kafka cho internal events. gRPC cho internal real-time communication.`,keywords:[`REST`,`gRPC`,`Kafka`,`event-driven`,`API Gateway`]},{id:`s02`,topic:`Microservices`,difficulty:4,question:`Saga pattern chi tiết. Choreography vs Orchestration? Distributed transaction trong microservices?`,sampleAnswer:`Saga: chia distributed transaction thành local transactions, mỗi step có compensating action nếu fail. Choreography: mỗi service emit event khi hoàn thành, service khác lắng nghe. Đơn giản, ít coupling nhưng khó trace và có thể circular dependency. Orchestration: có orchestrator (service) điều khiển flow, gọi từng service, handle fail. Dễ quản lý nhưng orchestrator là single point of failure. VD order: Order Service → Payment Service → Inventory Service → Shipping. Nếu payment fail → compensating: cancel order, release inventory. Implement: Kafka + CDC, hoặc Camunda BPMN. Không nên dùng 2PC (XA block) cho microservices.`,keywords:[`Saga`,`choreography`,`orchestration`,`compensating transaction`,`eventual consistency`]},{id:`s03`,topic:`Docker`,difficulty:2,question:`Docker multi-stage build, docker-compose, health check. Best practices cho Dockerfile?`,sampleAnswer:`Multi-stage: Stage 1 (build) dùng JDK + Maven build jar. Stage 2 (runtime) copy jar vào JDK/JRE image nhỏ. VD: maven:3.8-eclipse-temurin-17 AS build → javac + package → eclipse-temurin:17-jdk-alpine, copy --from=build app.jar. Best practices: 1. Dùng .dockerignore (node_modules, target). 2. Layer tối ưu — COPY pom.xml && RUN maven dependency:go-offline trước COPY source. 3. Dùng image nhỏ (alpine, distroless). 4. HEALTHCHECK — curl endpoint. 5. Chạy app với non-root user. docker-compose: định nghĩa multi-container (app, DB, Redis, Kafka). depends_on + healthcheck cho startup ordering.`,keywords:[`multi-stage`,`Dockerfile`,`alpine`,`HEALTHCHECK`,`docker-compose`]},{id:`s04`,topic:`Kubernetes`,difficulty:3,question:`Kubernetes Pod, Service, Deployment, StatefulSet, ConfigMap, Secret — khác nhau thế nào?`,sampleAnswer:`Pod: đơn vị nhỏ nhất — 1+ container, share network/storage. Không deploy Pod trực tiếp. Deployment: quản lý ReplicaSet, rolling update, rollback. Dùng cho stateless apps. StatefulSet: stable network ID, stable storage (PVC), ordered deployment. Dùng cho DB, Kafka, Elasticsearch. Service: expose Pods — ClusterIP (internal), NodePort (external), LoadBalancer (cloud). ConfigMap: inject config (file, env). Secret: inject sensitive data (base64 encoded, nhưng cần encryption thêm). Ingress: route external HTTP/HTTPS. Liveness probe: restart container khi chết. Readiness probe: không gửi traffic khi chưa sẵn sàng.`,keywords:[`Deployment`,`StatefulSet`,`Service`,`ConfigMap`,`liveness probe`]},{id:`s05`,topic:`Kafka`,difficulty:3,question:`Kafka: topic, partition, consumer group, offset, replication. Làm sao đảm bảo exactly-once?`,sampleAnswer:`Topic: category của messages. Partition: đơn vị parallelism — message trong partition có order. Consumer group: các consumer cùng group chia nhau partitions. Offset: vị trí message trong partition. Replication: leader-follower — nếu leader die, follower lên làm leader. Exactly-once: kết hợp idempotent producer (enable.idempotence=true) + transactional API + consumer cần lưu offset cùng kết quả xử lý trong cùng transaction. At-least-once: auto commit offset sau xử lý — có thể duplicate. At-most-once: auto commit offset trước xử lý — có thể mất message. Partition key: cùng key → cùng partition → ordered.`,keywords:[`partition`,`consumer group`,`offset`,`exactly-once`,`replication`]},{id:`s06`,topic:`Performance`,difficulty:3,question:`Caching strategy: Redis vs Local Cache? Cache Aside, Read Through, Write Through? Cho hệ thống 10k req/s.`,sampleAnswer:`Local Cache (Caffeine/Cache2k): siêu nhanh (microsecond), không network, giới hạn bộ nhớ 1 instance. Dùng cho: reference data (tỉnh, danh mục), config. Redis: distributed, shared giữa instances, có persistence, pub/sub. Dùng cho: session, rate limit, hot data. Cache Aside: app tự manage — đọc cache → miss → đọc DB → ghi cache. Phổ biến nhất. Read Through: cache tự động load từ DB khi miss — cache provider biết cách load. Write Through: ghi DB + cache đồng thời — consistency cao, latency cao hơn. Write Behind: ghi cache trước, async ghi DB — nhanh, risk mất dữ liệu. Cho 10k req/s: Caffeine L1 + Redis L2. Cache Aside pattern. TTL hợp lý (vài phút đến vài giờ).`,keywords:[`Redis`,`Caffeine`,`Cache Aside`,`TTL`,`distributed cache`]},{id:`s07`,topic:`Design Patterns`,difficulty:2,question:`Singleton pattern trong Java — các cách implement thread-safe. Enum vs Bill Pugh?`,sampleAnswer:`1. Eager initialization: private static final INSTANCE = new Singleton() — thread-safe, nhưng tạo ngay cả khi không dùng. 2. Synchronized method: public synchronized static getInstance() — chậm. 3. Double-checked locking: volatile + synchronized block — nhanh, phức tạp. 4. Bill Pugh (inner static class): private static class Holder { static final INSTANCE = new Singleton(); } — JVM lazy-load, thread-safe. 5. Enum: public enum Singleton { INSTANCE } — đơn giản nhất, chống reflection/serialization. Khuyên dùng: enum nếu không cần lazy init quá phức tạp, Bill Pugh cho mọi trường hợp khác.`,keywords:[`Singleton`,`Bill Pugh`,`double-checked locking`,`enum`,`thread-safe`]},{id:`s08`,topic:`Cloud`,difficulty:3,question:`Thiết kế hệ thống upload file hàng triệu user. Architecture, sizing, caching, CDN.`,sampleAnswer:`1. Client gửi request upload → API Gateway → app server. 2. App server generate presigned URL (S3 signed URL) — tối đa 5 phút. 3. Client upload trực tiếp lên S3 qua presigned URL — không qua app server (giảm load). 4. S3 event trigger Lambda để resize ảnh (thumbnail, medium, large) + lưu metadata vào DB. 5. Serve file qua CDN (CloudFront) — cache ở edge locations. 6. Download: client request CDN URL, miss thì CDN fetch từ S3 gốc. Sizing: S3 scale unlimited, không cần worry. CDN: giảm latency 70-80%. Security: presigned URL có expiry + IP restriction. Bucket policy: chỉ allow upload từ presigned URL.`,keywords:[`presigned URL`,`S3`,`CDN`,`Lambda`,`CloudFront`]},{id:`s09`,topic:`Microservices`,difficulty:4,question:`API Gateway pattern: chức năng, cách triển khai, so sánh Kong, Spring Cloud Gateway, Envoy.`,sampleAnswer:`API Gateway: single entry point cho tất cả services. Chức năng: routing, authentication, rate limiting, caching, request/response transformation, load balancing, circuit breaker, logging. Kong: mature API gateway, plugin ecosystem (OAuth2, rate limit, IP restriction), dùng Nginx + Lua, có DB (PostgreSQL/Cassandra). Spring Cloud Gateway: reactive (WebFlux), Java config, dễ tích hợp Spring ecosystem, non-blocking. Envoy: L7 proxy/service mesh, high-performance (C++), sidecar pattern, dùng trong Istio. Chọn: Kong cho API management enterprise. Spring Cloud Gateway cho Java shop. Envoy cho service mesh (Kubernetes). Lưu ý: API Gateway không nên có business logic.`,keywords:[`API Gateway`,`Kong`,`Spring Cloud Gateway`,`Envoy`,`rate limiting`]},{id:`s10`,topic:`Performance`,difficulty:3,question:`Connection pool sizing: HikariCP, PostgreSQL, công thức tính pool size tối ưu?`,sampleAnswer:`Công thức: pool_size = (core_count * 2) + effective_spindle_count. Với SSD, effective_spindle_count = 1. Với DB, connection pool không nên quá lớn — bottleneck là DB CPU/disk, không phải số connections. Nếu DB có 4 core: pool size ~ 9-12 là đủ. Pool quá lớn gây context switching trên DB. HikariCP: nhanh nhất Java pool, configure: maximumPoolSize=10, minimumIdle=5, idleTimeout=300000, connectionTimeout=30000, maxLifetime=1800000. Metrics: monitor active/idle/pending connections. Nếu pending > 0 thường xuyên → tăng pool từ từ. DB side: kiểm tra max_connections PostgreSQL (mặc định 100).`,keywords:[`HikariCP`,`connection pool`,`pool sizing`,`max_connections`,`context switching`]},{id:`s11`,topic:`Design Patterns`,difficulty:2,question:`Factory Pattern vs Strategy Pattern vs Builder Pattern — khác nhau, ví dụ thực tế.`,sampleAnswer:`Factory Method: tạo object, subclass quyết định class nào. VD: PaymentFactory.createPayment("credit_card") → CreditCardPayment. Strategy: chọn thuật toán tại runtime. VD: PaymentStrategy — CreditCardStrategy vs PayPalStrategy, context nhận strategy. Builder: xây dựng object phức tạp step-by-step. VD: OrderBuilder.addItem(x).setShipping(s).setPayment(p).build(). So sánh: Factory giấu creation logic, Strategy thay đổi behavior, Builder xây object từng bước. Kết hợp: Strategy Pattern trong Factory — factory tạo strategy object. Builder pattern hay dùng với immutable objects (Lombok @Builder).`,keywords:[`Factory`,`Strategy`,`Builder`,`creational pattern`,`behavioral pattern`]},{id:`s12`,topic:`Kubernetes`,difficulty:3,question:`Kubernetes scaling: HPA (Horizontal Pod Autoscaler), VPA, Cluster Autoscaler. Cấu hình thế nào?`,sampleAnswer:`HPA: scale số pod dựa trên CPU/memory/custom metrics (Prometheus). VD: hpa.yml — minReplicas: 3, maxReplicas: 20, targetCPUUtilizationPercentage: 70. Khi CPU > 70% → tăng pod. Lag: metrics server cần mấy chục giây. VPA: scale resources (CPU/memory) của pod — thay đổi requests/limits. Dùng cho stateful apps khó scale ngang. Cluster Autoscaler: scale số lượng node trong cluster khi không đủ resources. Scale up khi pod pending, scale down khi node underutilized. Best practices: HPA cho stateless apps request-response. VPA cho apps cần tuning. Cluster Autoscaler + HPA để tiết kiệm cost. PodDisruptionBudget cho availability khi scale down.`,keywords:[`HPA`,`VPA`,`Cluster Autoscaler`,`horizontal scaling`,`PodDisruptionBudget`]},{id:`s13`,topic:`Observability`,difficulty:3,question:`Observability: logging, metrics, tracing. ELK, Prometheus, Jaeger — cách tích hợp với Spring Boot?`,sampleAnswer:`3 pillars: Logging (structured, centralized), Metrics (Prometheus), Tracing (distributed tracing). Logging: Logback + ELK (Elasticsearch, Logstash, Kibana). Dùng JSON format, MDC cho correlation ID (traceId, spanId, userId). Metrics: Micrometer + Prometheus. Actuator expose /actuator/prometheus. Prometheus scrape metrics, Grafana dashboard. Custom metrics: @Timed, Counter, Gauge, Timer. Tracing: Spring Cloud Sleuth (add traceId/spanId tự động vào logs). Jaeger/Zipkin cho distributed tracing visualization. VD: request qua 3 services → 1 trace ID, 3 spans. Spring Boot 3.x dùng Micrometer Tracing (replaces Sleuth). Production checklist: centralized logging (ELK hoặc Loki), 4 golden signals (latency, traffic, errors, saturation) on Grafana.`,keywords:[`ELK`,`Prometheus`,`Jaeger`,`Micrometer`,`distributed tracing`]},{id:`s14`,topic:`Microservices`,difficulty:4,question:`Circuit Breaker pattern: cách implement với Resilience4j, các trạng thái, khi nào mở/đóng/half-open?`,sampleAnswer:`Circuit Breaker có 3 trạng thái: CLOSED (bình thường — request qua), OPEN (fail threshold → chặn request, throw exception hoặc fallback), HALF_OPEN (sau timeout → thử 1 request → thành công thì CLOSED, fail thì OPEN). Cấu hình Resilience4j: failureRateThreshold=50 (50% fail → mở), waitDurationInOpenState=10000ms (10s sau thử lại), slidingWindowSize=10 (10 requests gần nhất), permittedNumberOfCallsInHalfOpenState=3. Fallback: khác với retry — fallback trả về cached data hoặc response mặc định. Retry: retry N lần khi fail — không giải quyết được vấn đề dependency đang chết, có thể làm tình hình tệ hơn (retry storm). Bulkhead: giới hạn số concurrent calls — cô lập failure.`,keywords:[`Circuit Breaker`,`Resilience4j`,`HALF_OPEN`,`fallback`,`bulkhead`]},{id:`s15`,topic:`Kafka`,difficulty:3,question:`Kafka Streams vs Kafka Consumer: khác nhau? Xử lý event time vs processing time? Windowing?`,sampleAnswer:`Kafka Consumer: low-level — poll messages, xử lý, commit offset. Cần tự manage state, exactly-once phức tạp. Kafka Streams: high-level DSL — map, filter, join, aggregate, windowing. Tự động manage state (RocksDB), exactly-once built-in. Event time: thời gian message được tạo ra. Processing time: thời gian consumer xử lý. Watermark: theo dõi event time progress, handle late data (allow lateness). Window: tumbling window (cố định, không overlap), hopping window (có overlap), sliding window (theo timestamp), session window (theo inactivity gap). VD: đếm số click theo giờ — tumbling window 1 giờ. Lưu ý: event time yêu cầu timestamp trong message, consumer clock không ảnh hưởng.`,keywords:[`Kafka Streams`,`Kafka Consumer`,`event time`,`windowing`,`watermark`]},{id:`s16`,topic:`Cloud`,difficulty:3,question:`Thiết kế hệ thống real-time notification cho 10M users: push notification, email, SMS. Architecture?`,sampleAnswer:`1. User tạo notification request → API Gateway → Notification Service. 2. Notification Service ghi vào DB + push event lên Kafka (topic: notification). 3. Multiple consumers: Push Worker (FCM/APNs), Email Worker (SendGrid/SES), SMS Worker (Twilio). 4. Mỗi worker có riêng consumer group, độc lập scaling. 5. User preferences: push, email, SMS — lưu trong user profile. 6. Rate limiting: tránh spam (10 notification/phút/user). 7. Batch processing: email worker gom 100 emails → gửi 1 request (SES bulk). 8. Retry + dead letter queue (DLQ) cho failed notifications. 9. FCM: tối đa 4KB payload, dùng data message (app xử lý) thay vì notification message (system). 10. Monitoring: notification delivery rate, open rate, bounce rate.`,keywords:[`FCM`,`APNs`,`Kafka`,`rate limiting`,`dead letter queue`]}]},{id:`expert`,range:`70 triệu +`,min:70,max:200,label:`Tech Lead / Architect`,color:`#ef4444`,icon:`🏗️`,description:`8+ năm kinh nghiệm. Cần tầm nhìn kiến trúc, system design, distributed systems, technical leadership.`,topics:[`System Design: scalability, availability, consistency trade-offs, estimation`,`Distributed Systems: CAP theorem, consensus (Raft/Paxos), distributed storage, CRDT`,`High Availability: failover, disaster recovery, SLI/SLO/SLA, chaos engineering`,`Tech Leadership: code review, mentoring, technical decision making, RFC process`,`System Design Patterns: CQRS, Event Sourcing, Saga, Outbox, Caching layered`],questions:[{id:`e01`,topic:`System Design`,difficulty:5,question:`Thiết kế URL shortener (bit.ly) — 100M URLs/month. Estimations, DB schema, API design, caching strategy.`,sampleAnswer:`Estimations: 100M URLs/month = 37 URLs/s. Write: 37/s. Read: 370/s (10:1 read/write). Storage: 100M * 500 bytes ≈ 50GB/year. DB Schema: id (bigint auto-increment), shortCode (varchar(7) unique), originalUrl (text), createdAt, expiresAt, clickCount. API: POST /shorten { url, expires? } → { shortCode, shortUrl }, GET /{shortCode} → redirect 301. Hash: MD5(url) → base62 (7 ký tự = 62^7 ≈ 3.5 nghìn tỷ). Collision check + retry. Cache: Redis — cache hot URLs (LRU, TTL 24h). 80% traffic từ 20% URLs. Giả sử cache 1M URLs → ~100MB RAM. DB sharding theo shortCode hash. Rate limiting: 100 req/minute/user = 1M requests/month limit.`,keywords:[`base62`,`Redis cache`,`sharding`,`301 redirect`,`rate limiting`]},{id:`e02`,topic:`System Design`,difficulty:5,question:`Thiết kế hệ thống real-time chat cho 10M concurrent users. WebSocket, storage, offline message, end-to-end encryption.`,sampleAnswer:`1. WebSocket Gateway cluster — horizontal scale (10k connections/server → 1000 servers). Dùng HAProxy/Nginx + sticky session hoặc Redis pub/sub để broadcast message giữa servers. 2. Chat Service: nhận message, validate, ghi vào DB, push lên Kafka (topic: message). 3. Online Broadcast: Kafka → WebSocket Gateway → user. 4. Storage: Message — Cassandra hoặc ScyllaDB (write-optimized, partition theo conversationId, clustering key timestamp). User metadata — PostgreSQL. Attachment — S3 + CDN. 5. Offline message: user online lại → sync messages từ lastReadMessageId. 6. End-to-end encryption (E2EE): Signal Protocol (X3DH + Double Ratchet) — server không thể đọc nội dung. 7. Presence: Redis bitmap — online/offline status, TTL 5 giây (heartbeat). 8. Typing indicator: WebSocket emit typing → Redis pub/sub → giới hạn 1 event/3s để tránh spam. 9. File upload: presigned URL S3, scan virus (ClamAV). 10. Rate limiting: 30 messages/second/user.`,keywords:[`WebSocket`,`Cassandra`,`Kafka`,`E2EE`,`Signal Protocol`]},{id:`e03`,topic:`Distributed`,difficulty:5,question:`CAP theorem và PACELC — giải thích. Chọn CP hay AP và trade-offs thực tế?`,sampleAnswer:`CAP: Consistency (mọi node thấy data giống nhau), Availability (mọi request đều có response), Partition tolerance (hệ thống hoạt động khi network partition). Trong partition, chọn C hoặc A. PACELC: If partitioned (P) → trade-off A vs C. Else (E) → trade-off L (latency) vs C (consistency). Chọn CP: banking, payment — consistency quan trọng hơn availability. VD: khi partition, chặn write đến khi heal. Chọn AP: social media, CDN — availability quan trọng hơn. VD: Facebook chấp nhận user thấy data cũ. Trade-offs thực tế: CP không có nghĩa là không available hoàn toàn — các partition vẫn available riêng (CP/AP per partition). Eventual consistency + conflict resolution (CRDT) cho cả AP và C. Zookeeper/etcd: CP (quorum write). Cassandra: AP (tunable consistency — read/write consistency level).`,keywords:[`CAP`,`PACELC`,`consistency`,`availability`,`eventual consistency`]},{id:`e04`,topic:`System Design`,difficulty:5,question:`Thiết kế hệ thống real-time collaborative editor (Google Docs). CRDT vs OT, architecture?`,sampleAnswer:`Architecture: WebSocket → OT/CRDT server → MongoDB (snapshot) + Kafka (operations log). OT (Operational Transform): mỗi operation (insert, delete) được transform để merge với concurrent operations. Dùng trong Google Docs, ShareJS. Phức tạp, khó scale. CRDT (Conflict-free Replicated Data Types): mỗi character có unique ID, merge luôn đúng bất kể thứ tự. Ví dụ: Yjs, Automerge. Dễ scale, offline-first. Storage: document → MongoDB (full snapshot). Operations → Kafka (append-only log, replay để rebuild state). Client: Yjs WebSocket provider. Cursor: broadcast cursor position (không cần CRDT). Undo: lưu local undo stack — mỗi user undo riêng. Caching: Redis cache hot documents. Collaboration awareness: list user đang online + cursor positions.`,keywords:[`CRDT`,`Operational Transform`,`Yjs`,`MongoDB`,`WebSocket`]},{id:`e05`,topic:`Leadership`,difficulty:4,question:`Làm thế nào để đưa ra technical decision khi team disagree? RFC process, POC, trade-off matrix.`,sampleAnswer:`RFC (Request for Comments) process: 1. Context — vấn đề gì, tại sao cần quyết định. 2. Options — ít nhất 2 giải pháp khả thi. 3. Trade-offs — mỗi option có ưu/nhược điểm, cost, effort, risk. 4. Recommendation — option được đề xuất + rationale. 5. Comments — team review, feedback, biểu quyết. POC (Proof of Concept): với quyết định lớn (công nghệ mới), làm POC nhỏ (1-2 tuần) để validate. Trade-off matrix: trọng số hóa các tiêu chí (performance, maintainability, cost, learning curve, ecosystem). "Disagree and commit": sau khi thảo luận, leader quyết định — team commit dù có disagree. Data-driven: thu thập metrics từ POC/production proof. Nguyên tắc: disagree respectfully, discuss facts, commit wholeheartedly.`,keywords:[`RFC`,`POC`,`trade-off`,`technical decision`,`disagree and commit`]},{id:`e06`,topic:`High Availability`,difficulty:4,question:`SLA, SLI, SLO khác nhau? Tính availability chi tiết. 99.9% vs 99.99% khác nhau thế nào?`,sampleAnswer:`SLI (Service Level Indicator): metric đo — latency p99, error rate, throughput. SLO (Service Level Objective): mục tiêu — p99 latency < 200ms 99.9% thời gian. SLA (Service Level Agreement): cam kết với khách hàng — nếu vi phạm, bồi thường (thường SLO thấp hơn SLA). Tính availability: 99.9% = 8.76 giờ downtime/năm. 99.99% = 52.56 phút/năm. 99.999% = 5.26 phút/năm. Chi phí tăng exponential: 99.9% (2 server), 99.99% (5+ server, multi-region), 99.999% (global load balancer, active-active multi-region, chaos engineering). Error budget: (1 - SLO) * total time. VD: 99.9% SLO → 0.1% * 365 ngày = 8.76 giờ error budget/năm. Dùng error budget để quyết định release — nếu còn budget → release, hết → focus stability.`,keywords:[`SLA`,`SLO`,`SLI`,`error budget`,`downtime`]},{id:`e07`,topic:`System Design`,difficulty:5,question:`CQRS + Event Sourcing chi tiết. Khi nào nên dùng? Event store implementation, projection, snapshot.`,sampleAnswer:`CQRS (Command Query Responsibility Segregation): tách write model (commands) và read model (queries). Event Sourcing: lưu tất cả events thay vì current state. State có thể rebuild từ events. Khi nào dùng: audit log bắt buộc (finance, healthcare), complex business rules (order, inventory), temporal queries (state tại thời điểm bất kỳ), eventual consistency chấp nhận được. Không dùng: CRUD đơn giản, cần eventual consistency mạnh, team chưa quen. Event store: EventStoreDB, PostgreSQL (events table), Kafka cho event streaming. Projections: từ events → tạo read models. Snapshot: lưu state định kỳ (mỗi 100 events) để rebuild nhanh — không cần replay tất cả events. CQRS + ES + Saga = kiến trúc mạnh cho microservices.`,keywords:[`CQRS`,`Event Sourcing`,`Event Store`,`projection`,`snapshot`]},{id:`e08`,topic:`Distributed`,difficulty:5,question:`Raft consensus algorithm — leader election, log replication, safety. So sánh với Paxos?`,sampleAnswer:`Raft: dễ hiểu hơn Paxos — chia thành 3 subproblems: Leader Election, Log Replication, Safety. Terms: time chia thành term, mỗi term có tối đa 1 leader. Leader Election: follower → candidate → gửi RequestVote → nhận majority → leader. Nếu không có leader trong election timeout → new election. Log Replication: leader nhận client request → thêm vào local log → gửi AppendEntries đến followers → majority confirmed → commit. Safety: mỗi term chỉ có 1 leader. Leader không xóa log entry đã commit. Chỉ leader được append entries. So sánh Paxos: Paxos complex (multiple roles, proposal/accept phases), khó implement đúng. Raft: decomposition rõ ràng, strong leader, có journal/state machine model. Dùng Raft: etcd, Consul, Kafka KRaft. Dùng Paxos: Google Chubby, Spanner.`,keywords:[`Raft`,`leader election`,`log replication`,`Paxos`,`quorum`]},{id:`e09`,topic:`System Design`,difficulty:5,question:`Thiết kế hệ thống recommendation cho e-commerce: 100M users, 10M products. Collaborative vs Content-based filtering, online/offline training.`,sampleAnswer:`Architecture: Data Pipeline → Feature Store → Model Training → Serving → API. Offline: Spark jobs tính offline recommendations hàng ngày. Collaborative Filtering: ALS (Alternating Least Squares) — user-item matrix factorization. Output: user vectors, item vectors. Content-based: TF-IDF trên product description, category, tags. Hybrid: weighted combination. Real-time: user click → Kafka → real-time feature update → update recommendations (Flink/Redis). Online serving: Redis cache top-100 recommendations/user. API: GET /recommend?userId=X → lấy từ Redis → nếu miss → query from DB. A/B testing: 10% users thử model mới. Cold start: new user → recommend popular items + category-based. New item → content-based (description similarity). Feature Store (Feast): centralized features (user: gender, age, purchase history. item: category, price, rating). Model update: weekly full training, daily incremental.`,keywords:[`collaborative filtering`,`ALS`,`content-based`,`feature store`,`A/B testing`]},{id:`e10`,topic:`Leadership`,difficulty:4,question:`Code review best practices cho team. Làm sao để review hiệu quả không gây conflict?`,sampleAnswer:`Author side: 1. PR nhỏ — < 400 lines, 1 feature/PR. 2. Description rõ: "What + Why + How". 3. Self-review trước khi assign. 4. Test kèm PR (unit test, integration test). Reviewer side: 1. Review trong 24h (nếu quá lâu, dùng SLA: 1 business day). 2. Phân loại comments: blocking (phải fix), nitpick (nên fix), question (cần clarification). 3. Focus trên logic, architecture, security, test coverage, không style (dùng formatter). 4. "Why not how" — hỏi lý do, không dictate solution. 5. Positive feedback — "good catch", "nice refactor". Conflict resolution: nếu disagree → discuss offline, data-driven (POC/metrics). "If it takes > 15 phút debate, it's not important enough — ship it". Checklist: security (SQL injection, XSS), performance (N+1, indexing), error handling (getMessage, stacktrace), logging (context + correlation ID), monitoring metrics. Automation: CI check style, security scan, test coverage gate.`,keywords:[`code review`,`PR size`,`blocking comment`,`nitpick`,`automation`]},{id:`e11`,topic:`Distributed`,difficulty:5,question:`Distributed lock: Redis Redlock vs ZooKeeper vs etcd. Khi nào cần? Làm sao handle lock expiration?`,sampleAnswer:`Khi cần distributed lock: cron job chỉ 1 instance chạy, migrate dữ liệu không được chạy đồng thời, resource shared giữa services (ví dụ: xử lý 1 order 1 lần). Redis Redlock: SET resource uuid NX PX 30000 → 3 Redis instances độc lập → majority (> 2/3) = lock acquired. Nhược: clock drift có thể gây vấn đề (Redis đề nghị không dùng Redlock trong doc). ZooKeeper: ephemeral sequential znode — tạo node, nếu node tồn tại → lock fail. Watch node để nhận notification khi lock release. etcd: campaign/election API — lease-based, tự động release khi mất kết nối. Lock expiration: luôn có fence token/epoch — tăng dần mỗi lock. Kiểm tra token trước khi write DB. Dùng Redlock cho simple cases (latency-tolerant), ZooKeeper/etcd cho consistency-critical.`,keywords:[`Redlock`,`ZooKeeper`,`etcd`,`fence token`,`distributed lock`]},{id:`e12`,topic:`System Design`,difficulty:4,question:`Thiết kế hệ thống rate limiting cho API: algorithm (Token bucket, Leaky bucket, Sliding window), distributed rate limiting.`,sampleAnswer:`Algorithms: Token Bucket — bucket chứa N tokens, refill rate R/s. Mỗi request tiêu tốn 1 token. Supports bursts. Leaky Bucket — queue size N, process rate R/s. Request vào queue, nếu queue full → reject. Làm mượt traffic, không burst. Sliding Window Log — log timestamp của mỗi request, count trong window (VD: 60s). Chính xác nhưng tốn bộ nhớ. Sliding Window Counter — chia window thành slots, dùng counter. Tối ưu hơn log. Distributed rate limiting: Redis Sorted Set (ZADD timestamp, ZREMRANGEBYSCORE), ZCOUNT để đếm requests trong window. Lua script cho atomicity. Hoặc dùng Redis Rate Limiter module. Token Bucket + Redis: key = userId, field = tokens, timestamp. Lua script: lấy tokens, nếu < 0 reject. Cluster mode: hash theo userId — tất cả request của user đến 1 node. Rate limit headers: X-RateLimit-Limit, X-RateLimit-Remaining, X-RateLimit-Reset. Response 429 Too Many Requests + Retry-After.`,keywords:[`Token Bucket`,`Sliding Window`,`Redis`,`429 Too Many Requests`,`Lua script`]}]}],getTier(e){for(let t=this.tiers.length-1;t>=0;t--)if(e>=this.tiers[t].min)return this.tiers[t];return this.tiers[0]},getNextTier(e){let t=this.tiers.findIndex(t=>t.id===e);return t>=0&&t<this.tiers.length-1?this.tiers[t+1]:null},getTotalQuestions(){return this.tiers.reduce((e,t)=>e+t.questions.length,0)}};var h=window.salaryInterviewData,g={name:`SalaryInterviewPage`,data(){return{tiers:h.tiers,activeSalary:20,customSalary:20,customRequest:``,isGenerating:!1,questions:[]}},computed:{activeTier(){return h.getTier(this.activeSalary)},nextTier(){return h.getNextTier(this.activeTier?.id)}},methods:{handleNavigate(e){m(e)},selectTier(e){this.activeSalary=e.min,this.customSalary=e.min,this.questions=[]},stars(e){return`⭐`.repeat(Math.min(e,5))+`○`.repeat(Math.max(0,5-e))},async generate(){this.isGenerating=!0;let e=this.activeSalary,t=this.activeTier,n=this.customRequest.trim(),r=[...t?.questions||[]];try{let t=new AbortController,i=setTimeout(()=>t.abort(),8e3),a=await fetch(`/api/salary-interview`,{method:`POST`,headers:{"Content-Type":`application/json`},body:JSON.stringify({salary:e,customRequest:n||``,topic:`Java Backend`}),signal:t.signal});if(clearTimeout(i),a.ok){let e=await a.json();e.questions?.length&&(r=[...r,...e.questions.map((e,t)=>({...e,id:`ai-`+t,fromAI:!0}))])}}catch(e){console.warn(`Salary interview API error:`,e)}this.questions=r,this.isGenerating=!1}},watch:{customSalary(e){let t=Math.max(8,Math.min(200,e||8));this.activeSalary=t,this.questions=[]}}},_={class:`page-root`,style:{"--color-accent":`#7c5cfc`}},v={class:`page`},y={class:`topbar`},b={class:`salary-card`},x={class:`tier-grid`},S=[`onClick`],C={class:`tier-icon`},w={class:`tier-label`},T={class:`tier-range`},E={class:`custom-salary-row`},D={key:0,class:`q-count`},O={class:`actions`},k=[`disabled`],A={key:0,class:`questions-container`},j={class:`questions-header`},M={class:`questions-desc`},N={class:`q-head`},P={class:`q-topic`},F={key:0,class:`q-diff`},I={class:`q-text`},L={class:`q-answer`},R={class:`answer-text`},z={key:0,class:`keywords`},B={key:0,class:`badge`},V={key:1,class:`next-tier`};function H(u,m,h,g,H,U){return o(),a(`div`,_,[c(`div`,v,[c(`div`,y,[m[5]||=c(`h1`,null,`💰 Phỏng vấn theo lương`,-1),c(`button`,{class:`back`,onClick:m[0]||=e=>U.handleNavigate(`/`)},`← Trang chủ`)]),m[13]||=c(`p`,{class:`desc`},`Chọn mức lương mong muốn — hệ thống hiển thị câu hỏi phù hợp. Câu trả lời mẫu chi tiết kèm từ khóa. AI bổ sung theo yêu cầu.`,-1),c(`div`,b,[m[9]||=c(`h2`,null,`Chọn mức lương`,-1),m[10]||=c(`p`,null,`Bấm vào mức lương phù hợp — mỗi mức có bộ câu hỏi riêng. Bạn cũng có thể nhập số tùy chỉnh bên dưới.`,-1),c(`div`,x,[(o(!0),a(r,null,n(H.tiers,e=>(o(),a(`div`,{key:e.id,class:t([`tier-btn`,{active:U.activeTier?.id===e.id}]),onClick:t=>U.selectTier(e)},[c(`span`,C,f(e.icon),1),c(`span`,w,f(e.label),1),c(`span`,T,f(e.range),1),m[6]||=c(`span`,{class:`tier-check`},`✓`,-1)],10,S))),128))]),c(`div`,E,[m[7]||=c(`span`,{class:`custom-label`},`Hoặc nhập số:`,-1),p(c(`input`,{type:`number`,"onUpdate:modelValue":m[1]||=e=>H.customSalary=e,min:`8`,max:`200`,class:`custom-input`},null,512),[[s,H.customSalary,void 0,{number:!0}]]),m[8]||=c(`span`,{class:`custom-label`},`triệu/tháng`,-1)]),c(`div`,{class:`salary-tag`,style:e({background:U.activeTier?.color})},f(U.activeTier?.icon)+` `+f(U.activeTier?.label)+`: `+f(U.activeTier?.range),5),U.activeTier?(o(),a(`div`,D,` 📋 `+f(U.activeTier.questions.length)+` câu hỏi `,1)):i(``,!0),p(c(`input`,{type:`text`,class:`custom-input full`,"onUpdate:modelValue":m[2]||=e=>H.customRequest=e,placeholder:`Yêu cầu riêng? VD: focus Spring Boot & Microservices — AI bổ sung câu hỏi`,onKeydown:m[3]||=d((...e)=>U.generate&&U.generate(...e),[`enter`])},null,544),[[s,H.customRequest]]),c(`div`,O,[c(`button`,{class:`gen-btn`,disabled:H.isGenerating,onClick:m[4]||=(...e)=>U.generate&&U.generate(...e)},f(H.isGenerating?`⏳ Đang tạo...`:`🎯 Tạo câu hỏi`),9,k)])]),H.questions.length?(o(),a(`div`,A,[c(`h2`,j,`📋 `+f(H.questions.length)+` câu hỏi — `+f(U.activeTier?.range),1),c(`p`,M,f(U.activeTier?.icon)+` `+f(U.activeTier?.description),1),(o(!0),a(r,null,n(H.questions,(e,t)=>(o(),a(`div`,{key:e.id,class:`question`},[c(`div`,N,[c(`span`,P,f(e.topic||`Java`)+f(e.fromAI?` 🤖AI`:``),1),e.difficulty?(o(),a(`span`,F,f(U.stars(e.difficulty)),1)):i(``,!0)]),c(`div`,I,f(t+1)+`. `+f(e.question),1),c(`details`,L,[m[11]||=c(`summary`,null,`📝 Xem câu trả lời mẫu`,-1),c(`p`,R,f(e.sampleAnswer||`—`),1),e.keywords?.length?(o(),a(`div`,z,[(o(!0),a(r,null,n(e.keywords,e=>(o(),a(`span`,{key:e,class:`kw`},f(e),1))),128))])):i(``,!0)])]))),128)),U.activeTier?.topics?(o(),a(`div`,B,` 📌 Chủ đề: `+f(U.activeTier.topics.join(` • `)),1)):i(``,!0),U.nextTier?(o(),a(`div`,V,[m[12]||=l(` 💡 Mục tiêu: `,-1),c(`strong`,{style:e({color:U.nextTier.color})},f(U.nextTier.label)+` (`+f(U.nextTier.range)+`)`,5),l(` — `+f(U.nextTier.description),1)])):i(``,!0)])):i(``,!0)])])}var U=u(g,[[`render`,H],[`__scopeId`,`data-v-40918975`]]);export{U as default};